from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak, KeepTogether

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'PROJECT_REPORT.pdf'
AS=ROOT/'artifacts/report_assets'

styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='Title2', parent=styles['Title'], fontSize=22, leading=28, alignment=TA_CENTER, textColor=colors.HexColor('#17375e'), spaceAfter=14))
styles.add(ParagraphStyle(name='H1x', parent=styles['Heading1'], fontSize=15, leading=19, textColor=colors.HexColor('#17375e'), spaceBefore=8, spaceAfter=8))
styles.add(ParagraphStyle(name='Bodyx', parent=styles['BodyText'], fontSize=9.5, leading=14, spaceAfter=6))
styles.add(ParagraphStyle(name='Smallx', parent=styles['BodyText'], fontSize=8, leading=11, textColor=colors.HexColor('#555555')))

story=[]
story += [Paragraph('Banking Multi-Agent Support Bot', styles['Title2']),
          Paragraph('Project Documentation and Implementation Report', styles['Heading2']), Spacer(1,8),
          Paragraph('<b>Domain:</b> Banking customer support<br/><b>Classifier:</b> From-scratch Embedding + BiGRU<br/><b>Orchestration:</b> LangChain specialist agents<br/><b>Interface:</b> Streamlit', styles['Bodyx'])]

story += [Paragraph('1. Project Objective', styles['H1x']),
Paragraph('The application routes support messages to specialist agents using a trained deep-learning intent classifier. The classifier predicts one of five selected intents and produces a confidence score. A deterministic Python router maps that intent to one of four specialist agents. The selected agent then uses its own system prompt and tools to generate the response. This keeps the routing decision outside the language model.', styles['Bodyx']),
Image(str(AS/'architecture.png'), width=17.5*cm, height=10.5*cm)]

story += [PageBreak(), Paragraph('2. Domain, Intents, and Dataset', styles['H1x'])]
data=[['Intent','Agent'],['card_payment_fee_charged','Billing'],['cash_withdrawal_charge','Billing'],['card_not_working','Technical'],['order_physical_card','Booking / card-order'],['country_support','General']]
t=Table(data,colWidths=[10*cm,6*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17375e')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),0.4,colors.grey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8.5),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#eef3f9')])]))
story += [t, Spacer(1,10), Paragraph('BANKING77 is a public banking customer-service intent dataset. The selected MTEB version provides 77 labels and a 10,003-row training split with text, numeric label, and label_text fields. The project filters five intents and makes a stratified 80/10/10 split from the selected training examples.', styles['Bodyx']), Paragraph('Dataset source: https://huggingface.co/datasets/mteb/banking77', styles['Smallx'])]

story += [Paragraph('3. Deep Learning Classifier', styles['H1x']), Paragraph('The classifier is deliberately small and trainable from scratch. It uses a trainable word embedding, a bidirectional GRU, dropout, and a final linear classifier. Training uses Adam, cross-entropy loss, gradient clipping, and validation macro-F1 for checkpoint selection.', styles['Bodyx']), Image(str(AS/'model_code.png'), width=17.5*cm, height=8.0*cm)]

story += [PageBreak(), Paragraph('4. Evaluation and Verification', styles['H1x']), Paragraph('The project is designed to generate real test results from the held-out test split. Accuracy, macro-F1, a classification report, a confusion matrix, and one held-out misclassification example are saved under artifacts/.', styles['Bodyx'])]

metrics_file=ROOT/'artifacts/metrics.json'
if metrics_file.exists():
    import json
    m=json.loads(metrics_file.read_text())
    status=[['Metric','Value'],['Test accuracy',f"{m['test_accuracy']:.4f}"],['Test macro-F1',f"{m['test_macro_f1']:.4f}"],['Train examples',str(m['split_sizes']['train'])],['Validation examples',str(m['split_sizes']['validation'])],['Test examples',str(m['split_sizes']['test'])]]
else:
    status=[['Metric','Status'],['Test accuracy','Run training locally'],['Test macro-F1','Run training locally'],['Train examples','Generated by training script'],['Validation examples','Generated by training script'],['Test examples','Generated by training script']]

t=Table(status,colWidths=[8*cm,8*cm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17375e')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),0.4,colors.grey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8.5),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#eef3f9')])]))
story += [t, Spacer(1,10), Image(str(AS/'test_evidence.png'), width=15*cm, height=3.25*cm), Paragraph('Static verification performed in the build environment: all three project unit tests passed. The final ML accuracy/F1 numbers are intentionally not fabricated; they appear in artifacts/metrics.json after the BANKING77 training command is executed.', styles['Smallx'])]

for f, title in [('router_code.png','Routing implementation'),('agents_code.png','Specialist agents and tool definitions')]:
    story += [Spacer(1,8), Paragraph(title, styles['H1x']), Image(str(AS/f), width=17.5*cm, height=7.5*cm)]

story += [PageBreak(), Paragraph('5. RAG and Tools', styles['H1x']), Paragraph('The knowledge base contains 12 short Markdown articles. They are split into chunks, embedded with sentence-transformers/all-MiniLM-L6-v2, stored in a local FAISS index, and retrieved at runtime. The agents can call search_docs rather than receiving the entire knowledge base in every prompt.', styles['Bodyx']),
Paragraph('<b>Tools:</b> check_invoice(customer_id), check_availability(date), and search_docs(query). The invoice and appointment tools use deterministic demo data so the project does not connect to private banking systems.', styles['Bodyx']),
Paragraph('The local RAG setup avoids an external vector database and therefore keeps the demo inexpensive and easy to run.', styles['Bodyx'])]

story += [Paragraph('6. Conversation Memory', styles['H1x']), Paragraph('Streamlit session state stores the complete conversation. Before an agent call, previous user and assistant turns are converted into LangChain HumanMessage and AIMessage objects and passed as chat_history. Because the history is independent of the selected specialist, a later message can be routed to a different agent without losing the previous context.', styles['Bodyx'])]

story += [Paragraph('7. Streamlit Interface', styles['H1x']), Paragraph('The final interface has a main chat area and a routing sidebar. The sidebar reports the predicted intent, confidence, selected agent, provider, and session usage. The preview below shows the intended layout. For the final course submission, this preview should be replaced by screenshots captured from the actually running Streamlit application so that the screenshots match the recorded demo.', styles['Bodyx']), Image(str(AS/'streamlit_ui_preview.png'), width=17.5*cm, height=10.4*cm)]

story += [PageBreak(), Paragraph('8. Required Demo Cases', styles['H1x'])]
for x in [
    'Billing: “Why was I charged a fee for my card payment?”',
    'Billing: “Why did the ATM charge me a withdrawal fee?”',
    'Technical + RAG: “My card is not working.”',
    'Booking: “How do I order a physical card?”',
    'General: “Which countries do you support?”',
    'Tool call: include a billing request with customer ID C1001 so check_invoice can be demonstrated.',
    'Tool call: ask for support appointment availability on a weekday such as 2026-10-10.',
    'Fallback: disable the primary LLM provider and demonstrate the offline response instead of a crash.'
]:
    story.append(Paragraph('• '+x, styles['Bodyx']))
story += [Paragraph('A complete 3–5 minute sequence is provided in DEMO_SCRIPT.md.', styles['Bodyx']),
          Paragraph('9. Free-Tier and Failure Handling', styles['H1x']),
          Paragraph('The app limits a session to 20 requests, keeps prompts short, retrieves only three RAG chunks, limits each agent to three iterations, and uses a Groq → Ollama fallback. If both providers fail, the router returns a short offline message and the Streamlit app remains usable.', styles['Bodyx']),
          Paragraph('10. Academic Integrity', styles['H1x']), Paragraph('AI assistance was used for development support. Generated source sections are marked with explicit AI-GENERATED SECTION START / END comments. The final submission should keep these markers and follow the instructor’s disclosure rules.', styles['Bodyx'])]

story += [PageBreak(), Paragraph('11. Final Submission Checklist', styles['H1x'])]
checks=['trained artifacts/classifier.pt','artifacts/metrics.json','artifacts/confusion_matrix.csv','artifacts/misroute_example.json','artifacts/confusion_matrix.png','artifacts/f1_by_intent.png','artifacts/faiss_index/','source code and tests','12 knowledge-base documents','requirements.txt and README.md','this PDF report','3–5 minute live Streamlit demo video']
for c in checks: story.append(Paragraph('☐ '+c, styles['Bodyx']))
story += [Spacer(1,10), Paragraph('Execution note', styles['H1x']), Paragraph('The codebase and unit tests were checked in the build environment. External package/dataset downloads are disabled in that environment, so the actual BANKING77 training checkpoint, final accuracy/F1, FAISS index, live Streamlit screenshots, and live demo recording must be generated on a machine with the required packages/network access. The project never substitutes invented evaluation numbers for those real outputs.', styles['Bodyx'])]


def footer(canvas, doc):
    canvas.saveState(); canvas.setFont('Helvetica',7); canvas.setFillColor(colors.grey)
    canvas.drawString(2*cm,1.1*cm,'Banking Multi-Agent Support Bot')
    canvas.drawRightString(A4[0]-2*cm,1.1*cm,f'Page {doc.page}')
    canvas.restoreState()

SimpleDocTemplate(str(OUT), pagesize=A4, rightMargin=1.7*cm,leftMargin=1.7*cm,topMargin=1.5*cm,bottomMargin=1.6*cm,title='Banking Multi-Agent Support Bot Report').build(story,onFirstPage=footer,onLaterPages=footer)
print(OUT)
